def rects(G,minside=4):
    H,W=len(G),len(G[0]); out=[]
    for top in range(H):
        same=[True]*W
        for bot in range(top,H):
            same=[same[j] and G[bot][j]==G[top][j] for j in range(W)]
            j=0
            while j<W:
                if not same[j]: j+=1; continue
                k=j+1
                while k<W and same[k]: k+=1
                if bot-top+1>=minside and k-j>=minside:
                    color=G[top][j]
                    out.append((color,(top,j,bot+1,k),(bot-top+1)*(k-j)))
                j=k
    return out
